import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { Button, Typography, Dropdown, Radio, Checkbox, Input, Slider, Menu, Select, Space, InputNumber, DatePicker, Modal, Tooltip, Col, Row } from 'antd';
import { DownOutlined, MenuOutlined, ArrowUpOutlined, ArrowDownOutlined, PlusOutlined, DeleteOutlined, SearchOutlined, CalendarOutlined, FilterOutlined, ArrowRightOutlined, CloseOutlined } from '@ant-design/icons';
import dayjs from 'dayjs';
import { sources, getSourceByCodename } from './data/sources';
import airlines from './data/airlines_full';
import { airportGroups, airportGroupDescriptions } from './data/airportGroups';
import { airports as airportsData } from './data/airports';

// Import split functionality
import { 
  getDaysInMonth,
  getFirstDayOfMonth,
  formatDate,
  isDateInRange,
  goToPrevMonth,
  goToNextMonth,
  handlePageChange
} from './utils/date-utils';

import {
  getEnrichedFlightData,
  getFilteredFlights,
  isValidSegmentForRoute,
  getUniqueSegments,
  getUniqueSources,
  getUniqueAirlines,
  getPointsRange,
  getUniqueDates,
  getFlightsForClassWithFilters,
  getOrderedSegments,
  getUniqueOriginAirports,
  getUniqueDestinationAirports,
  getAirportName,
  isRouteInFilterScope,
  sortSegments
} from './utils/flight-data-utils';

import {
  filterFlights,
  deleteFilter
} from './utils/filter-utils';

import {
  renderAvailabilityBadges,
  renderSegmentsDropdown,
  renderClassDropdown,
  renderGroupClassDropdown,
  renderSegmentClassDropdown,
  renderSourcesDropdown,
  renderGroupSourcesDropdown,
  renderSegmentSourcesDropdown,
  renderAirlinesDropdown,
  renderPointsDropdown,
  renderGroupPointsDropdown,
  renderSegmentPointsDropdown,
  renderDatesDropdown,
  renderGroupDatesDropdown,
  renderSegmentDatesDropdown,
  renderAdditionalFilter,
  renderOriginDropdown,
  renderDestDropdown,
  renderSegmentsDropdownSimple,
  addFilterMenu,
  renderGroupAirlinesDropdown,
  renderSegmentAirlinesDropdown
} from './components/calendar-renderers';

const { Title } = Typography;

const NormalFlightAvailabilityCalendar = ({ flightData, currentRoute, onDateRangeSelect, selectedRange }) => {
  // State initialization
  const [currentMonth, setCurrentMonth] = useState(dayjs().month());
  const [currentYear, setCurrentYear] = useState(dayjs().year());
  const [localSelectionStart, setLocalSelectionStart] = useState(null);
  const [localSelectionEnd, setLocalSelectionEnd] = useState(null);
  const [error, setError] = useState('');
  // Pagination state - store current page for each cell by date
  const [cellPages, setCellPages] = useState({});
  // Ref to track active tooltip ID
  const activeTooltipRef = useRef(null);
  // Segment filter state
  const [segmentFilter, setSegmentFilter] = useState({
    mode: 'include',
    segments: []
  });
  // Add search text state for segment filter
  const [segmentSearchText, setSegmentSearchText] = useState('');
  // Add segment order state to control the display order
  const [segmentOrder, setSegmentOrder] = useState([]);
  // Class filter state
  const [classFilter, setClassFilter] = useState([]);
  // Direct filter state
  const [directFilter, setDirectFilter] = useState(false);
  // Source filter state
  const [sourceFilter, setSourceFilter] = useState({
    mode: 'include',
    sources: []
  });
  // Add search text state for source filter
  const [sourceSearchText, setSourceSearchText] = useState('');
  // Points filter state
  const [pointsFilter, setPointsFilter] = useState(null);
  // Add airlines filter state
  const [airlinesFilter, setAirlinesFilter] = useState({
    mode: 'include',
    airlines: []
  });
  // Add search text state for airlines filter
  const [airlinesSearchText, setAirlinesSearchText] = useState('');
  // Date filter state
  const [dateFilter, setDateFilter] = useState([]);
  // Add search text state for date filter
  const [dateSearchText, setDateSearchText] = useState('');
  // Change additionalFilterType to an array of filter objects
  const [additionalFilters, setAdditionalFilters] = useState([]); // Array of {id, type} objects

  // Add state for group-based filters and segment-based filters
  const [groupFilters, setGroupFilters] = useState({}); // { filterId: { originFilter: {}, destFilter: {} } }
  const [segmentFilters, setSegmentFilters] = useState({}); // { filterId: { segments: [] } }

  // Search text states
  const [originSearchText, setOriginSearchText] = useState('');
  const [destSearchText, setDestSearchText] = useState('');

  // Search text states for group filters (using a map to support multiple groups)
  const [groupSourceSearchTexts, setGroupSourceSearchTexts] = useState({});
  const [groupAirlinesSearchTexts, setGroupAirlinesSearchTexts] = useState({});
  const [groupDateSearchTexts, setGroupDateSearchTexts] = useState({});

  // Search text states for segment filters (using a map to support multiple segments)
  const [segmentSourceSearchTexts, setSegmentSourceSearchTexts] = useState({});
  const [segmentAirlinesSearchTexts, setSegmentAirlinesSearchTexts] = useState({});
  const [segmentDateSearchTexts, setSegmentDateSearchTexts] = useState({});

  // Create derived values for selection that can be used in the component
  const selectionStart = localSelectionStart;
  const selectionEnd = localSelectionEnd;

  // Track selection changes with a ref to prevent race conditions
  const selectionRef = useRef({ start: null, end: null });

  // Sample raw response data for fallback
  const sampleRawData = useRef([
    {
      "originAirport": "LHR",
      "destinationAirport": "EWR",
      "date": "2025-03-28",
      "distance": 3459,
      "ID": "sample1",
      "source": "aeroplan",
      "YAvailable": true,
      "WAvailable": false,
      "JAvailable": true,
      "FAvailable": false,
      "YDirect": true,
      "WDirect": false,
      "JDirect": true,
      "FDirect": false,
      "YAirlines": "AC, LH, QK, UA",
      "WAirlines": "",
      "JAirlines": "UA",
      "FAirlines": "",
      "YDirectAirlines": "UA",
      "WDirectAirlines": "",
      "JDirectAirlines": "UA",
      "FDirectAirlines": "",
      "YMileageCost": "40000",
      "WMileageCost": "0",
      "JMileageCost": "80000",
      "FMileageCost": "0",
      "YTotalTaxes": 34639,
      "WTotalTaxes": 0,
      "JTotalTaxes": 55000,
      "FTotalTaxes": 0,
      "YDirectMileageCost": 40000,
      "WDirectMileageCost": 0,
      "JDirectMileageCost": 80000,
      "FDirectMileageCost": 0,
      "YDirectTotalTaxes": 35470,
      "WDirectTotalTaxes": 0,
      "JDirectTotalTaxes": 55000,
      "FDirectTotalTaxes": 0,
      "TaxesCurrency": "CAD"
    }
  ]);

  // Handle tooltip repositioning on window resize or scroll
  useEffect(() => {
    const handleWindowChange = () => {
      const tooltipId = activeTooltipRef.current;
      if (tooltipId) {
        const tooltip = document.getElementById(tooltipId);
        if (tooltip) {
          // Remove the tooltip if window size changes or scrolling occurs
          document.body.removeChild(tooltip);
          activeTooltipRef.current = null;
        }
      }
    };

    window.addEventListener('resize', handleWindowChange);
    window.addEventListener('scroll', handleWindowChange);

    return () => {
      window.removeEventListener('resize', handleWindowChange);
      window.removeEventListener('scroll', handleWindowChange);
    };
  }, []);

  // Use a separate useEffect to sync the selectedRange prop with local state
  useEffect(() => {
    if (selectedRange) {
      setLocalSelectionStart(selectedRange.start);
      setLocalSelectionEnd(selectedRange.end);
      selectionRef.current = { 
        start: selectedRange.start, 
        end: selectedRange.end 
      };
    }
  }, [selectedRange]);

  // Function to handle date click for selection
  const handleDateClick = (dateString) => {
    // Skip if date is not a string or is empty
    if (typeof dateString !== 'string' || dateString.trim() === '') {
      return;
    }

    // Clear error message
    setError('');

    // Current selection state from ref to avoid race conditions
    const currentSelection = selectionRef.current;

    // If no selection has started yet or both start/end are already set, start new selection
    if (!currentSelection.start || (currentSelection.start && currentSelection.end)) {
      setLocalSelectionStart(dateString);
      setLocalSelectionEnd(null);

      // Update ref
      selectionRef.current = { start: dateString, end: null };
    } 
    // If only start is set, complete the selection with end date
    else if (currentSelection.start && !currentSelection.end) {
      // Check if end date is before start date
      if (dayjs(dateString).isBefore(dayjs(currentSelection.start))) {
        // Swap dates if end is before start
        setLocalSelectionEnd(currentSelection.start);
        setLocalSelectionStart(dateString);

        // Update ref
        selectionRef.current = { 
          start: dateString, 
          end: currentSelection.start 
        };

        // Notify parent component of selection
        onDateRangeSelect && onDateRangeSelect({
          start: dateString,
          end: currentSelection.start
        });
      } else {
        setLocalSelectionEnd(dateString);

        // Update ref
        selectionRef.current = { 
          start: currentSelection.start, 
          end: dateString 
        };

        // Notify parent component of selection
        onDateRangeSelect && onDateRangeSelect({
          start: currentSelection.start,
          end: dateString
        });
      }
    }
  };

  // Render the calendar UI
  return (
    <div style={{ 
      fontFamily: 'Arial, sans-serif',
      maxWidth: '1200px', 
      margin: '0 auto',
      padding: '20px'
    }}>
      <div style={{ marginBottom: '16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Title level={4} style={{ margin: 0 }}>
          {dayjs().month(currentMonth).year(currentYear).format('MMMM YYYY')}
        </Title>
        <div>
          <Button 
            onClick={goToPrevMonth.bind(null, currentMonth, currentYear, setCurrentMonth, setCurrentYear)}
            style={{ marginRight: '8px' }}
          >
            Previous Month
          </Button>
          <Button 
            onClick={goToNextMonth.bind(null, currentMonth, currentYear, setCurrentMonth, setCurrentYear)}
          >
            Next Month
          </Button>
        </div>
      </div>

      <div style={{ marginBottom: '20px' }}>
        {/* Filters sections */}
        <div style={{ 
          background: '#f5f5f5', 
          padding: '15px', 
          borderRadius: '5px',
          marginBottom: '15px'
        }}>
          <Title level={4} style={{ marginTop: 0 }}>Filters</Title>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
            {renderSegmentsDropdown()}
            {renderClassDropdown()}
            {renderSourcesDropdown()}
            {renderAirlinesDropdown()}
            {renderPointsDropdown()}
            {renderDatesDropdown()}
          </div>

          {/* Additional filters section */}
          <div style={{ marginTop: '15px' }}>
            <div style={{ display: 'flex', alignItems: 'center', marginBottom: '10px' }}>
              <Title level={5} style={{ margin: 0, marginRight: '10px' }}>Additional Filters</Title>
              {addFilterMenu()}
            </div>

            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
              {renderAdditionalFilter()}
            </div>
          </div>
        </div>

        {/* Direct flights only checkbox */}
        <div style={{ marginBottom: '10px' }}>
          <Checkbox 
            checked={directFilter}
            onChange={(e) => setDirectFilter(e.target.checked)}
          >
            Direct flights only
          </Checkbox>
        </div>
      </div>

      <div style={{ background: '#fff', borderRadius: '8px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)', overflow: 'hidden' }}>
        {/* Calendar header with day names */}
        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: 'repeat(7, 1fr)',
          background: '#1890ff',
          color: 'white',
          fontWeight: 'bold'
        }}>
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
            <div key={day} style={{ padding: '12px', textAlign: 'center' }}>
              {day}
            </div>
          ))}
        </div>

        {/* Calendar days */}
        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: 'repeat(7, 1fr)',
          gap: '1px',
          background: '#f0f0f0'
        }}>
          {(() => {
            const days = [];
            const daysInMonth = getDaysInMonth(currentYear, currentMonth);
            const firstDayOfMonth = getFirstDayOfMonth(currentYear, currentMonth);

            // Add empty cells for days before the first day of the month
            for (let i = 0; i < firstDayOfMonth; i++) {
              days.push(
                <div 
                  key={`empty-${i}`} 
                  style={{ 
                    background: '#fff',
                    minHeight: '120px'
                  }}
                >
                </div>
              );
            }

            // Add cells for each day of the month
            for (let day = 1; day <= daysInMonth; day++) {
              const dateString = formatDate(currentYear, currentMonth, day);
              const isSelected = isDateInRange(dateString, selectionStart, selectionEnd);

              const baseRoute = currentRoute || 'LHR-JFK'; // fallback route
              const [origin, destination] = baseRoute.split('-');
              const routeKey = `${origin}-${destination}`;

              // Extract available classes from flightData for this date
              const dateData = flightData?.availability?.[routeKey]?.[dateString] || {};
              const classesData = flightData?.classes || ['Y', 'W', 'J', 'F']; // default classes

              days.push(
                <div 
                  key={day}
                  onClick={() => handleDateClick(dateString)}
                  style={{ 
                    background: isSelected ? '#e6f7ff' : '#fff',
                    border: isSelected ? '2px solid #1890ff' : '1px solid #f0f0f0',
                    padding: '8px',
                    cursor: 'pointer',
                    position: 'relative',
                    minHeight: '120px'
                  }}
                >
                  <div style={{ 
                    fontWeight: 'bold', 
                    marginBottom: '8px',
                    textAlign: 'right'
                  }}>
                    {day}
                  </div>

                  {/* Availability indicator badges */}
                  <div style={{ 
                    display: 'flex', 
                    flexDirection: 'column',
                    gap: '4px'
                  }}>
                    {renderAvailabilityBadges(routeKey, classesData, dateString)}
                  </div>
                </div>
              );
            }

            // Add empty cells for days after the last day of the month
            const totalCells = 42; // 6 rows of 7 days
            const remainingCells = totalCells - days.length;

            for (let i = 0; i < remainingCells; i++) {
              days.push(
                <div 
                  key={`empty-end-${i}`} 
                  style={{ 
                    background: '#fff',
                    minHeight: '120px'
                  }}
                >
                </div>
              );
            }

            return days;
          })()}
        </div>

        {/* Error message */}
        {error && (
          <div style={{ 
            color: '#ff4d4f', 
            marginTop: '16px',
            textAlign: 'center' 
          }}>
            {error}
          </div>
        )}
      </div>
    </div>
  );
};

export default NormalFlightAvailabilityCalendar;
